{
  "findings": [
    {
      "check_id": "CKV_GCP_102",
      "title": "Cloud Run service is publicly accessible",
      "resource": "google_cloud_run_service_iam_binding.search_service_public",
      "severity": "MEDIUM",
      "explanation": "The roles/run.invoker binding grants allUsers permission to invoke the Cloud Run service, allowing unauthenticated public access."
    }
  ],
  "patched_code": "resource \"google_cloud_run_service_iam_binding\" \"search_service_public\" {\n  location = google_cloud_run_service.search_service.location\n  project  = google_cloud_run_service.search_service.project\n  service  = google_cloud_run_service.search_service.name\n  role     = \"roles/run.invoker\"\n  members  = []\n}\n",
  "fix_summary": "Removed the allUsers principal from the Cloud Run invoker binding so the service is no longer anonymously accessible."
}
